package nl.voetbalhub.app;
import android.app.Activity;
import android.widget.*;
import org.json.*;
/** Rights-checked strip with no synthetic fixtures and no simulated live updates. */
public final class MatchStrip40 extends HorizontalScrollView {
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newFixedThreadPool(1);
 private final Activity a;private final LinearLayout row;private final Runnable action;private boolean attached;private JSONObject snapshot;private long lastAttempt;
 private final Runnable refresh=new Runnable(){public void run(){if(!attached)return;if(getWindowVisibility()==VISIBLE&&hasWindowFocus())load();postDelayed(this,60000);}};
 private int dp(float n){return PremiumDesign40.dp(a,n);}
 public MatchStrip40(Activity a,Runnable action){super(a);this.a=a;this.action=action;setHorizontalScrollBarEnabled(false);PremiumDesign40.card(this,PremiumDesign40.EDGE);row=new LinearLayout(a);row.setPadding(dp(8),dp(5),dp(8),dp(5));addView(row,new LayoutParams(-2,-2));try{snapshot=new JSONObject(a.getSharedPreferences("eredivisie-statistics",0).getString("snapshot","{}"));}catch(Exception ignored){}render();}
 private void load(){if(System.currentTimeMillis()-lastAttempt<45000)return;lastAttempt=System.currentTimeMillis();IO.execute(()->{JSONObject data=null;try{JSONObject r=new JSONObject(DeadlineHttp.get("https://voetbalhub-redactie.onrender.com/integrations/statistics",10000,2000000));if(PublicationPolicy.allows(r))data=r;}catch(Exception ignored){}final JSONObject result=data;a.runOnUiThread(()->{if(!attached)return;if(result!=null){snapshot=result;a.getSharedPreferences("eredivisie-statistics",0).edit().putString("snapshot",result.toString()).apply();}render();});});}
 private void render(){row.removeAllViews();JSONArray fs=snapshot!=null&&PublicationPolicy.allows(snapshot)?snapshot.optJSONArray("fixtures"):null;int count=0;long now=System.currentTimeMillis();if(fs!=null)for(int i=0;i<fs.length()&&count<10;i++){JSONObject f=fs.optJSONObject(i);if(f==null||f.optJSONObject("home")==null||f.optJSONObject("away")==null)continue;try{long at=java.time.Instant.parse(f.getString("date")).toEpochMilli();if(at<now-86400000||at>now+7L*86400000)continue;String status=f.optString("status"),value=java.time.format.DateTimeFormatter.ofPattern("EEE HH:mm",new java.util.Locale("nl","NL")).withZone(java.time.ZoneId.of("Europe/Amsterdam")).format(java.time.Instant.ofEpochMilli(at));JSONObject score=f.optJSONObject("goals");if(score==null)score=f.optJSONObject("score");if(java.util.Arrays.asList("FT","AET","PEN").contains(status)&&score!=null&&!score.isNull("home")&&!score.isNull("away"))value=score.getInt("home")+" – "+score.getInt("away")+" · Afgelopen";else if(!"NS".equals(status)&&!"TBD".equals(status))value="Status: "+status;JSONObject league=snapshot.optJSONObject("league");add(f.getJSONObject("home").optString("name")+" – "+f.getJSONObject("away").optString("name"),value+"\n"+(league==null?"":league.optString("name","")));count++;}catch(Exception ignored){}}
  if(count==0)add("Wedstrijden", "Geen gecontroleerde duels beschikbaar · Open overzicht");
 }
 private void add(String title,String subtitle){LinearLayout card=new LinearLayout(a);card.setOrientation(1);card.setGravity(android.view.Gravity.CENTER_VERTICAL);card.setPadding(dp(12),dp(9),dp(12),dp(9));TextView t=PremiumDesign40.text(a,title,12,PremiumDesign40.WHITE,true);card.addView(t);TextView s=PremiumDesign40.text(a,subtitle,10,PremiumDesign40.GREEN,false);s.setPadding(0,dp(5),0,0);card.addView(s);PremiumDesign40.touch(card);card.setContentDescription(title+". "+subtitle+". Wedstrijden openen");card.setOnClickListener(v->action.run());row.addView(card,new LinearLayout.LayoutParams(-2,dp(68)));}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;post(refresh);}
 @Override protected void onDetachedFromWindow(){attached=false;removeCallbacks(refresh);super.onDetachedFromWindow();}
}
